import{c as e,Q as r,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"The 12-Rule Canon for AI Coding Agents — Universal Edition","description":"","frontmatter":{"title":"The 12-Rule Canon for AI Coding Agents — Universal Edition","date":"2026-06-04T00:00:00.000Z","status":"complete","derived_from":["Karpathy R1–R4 (CLAUDE.md) + Mnilax R5–R12 (thread)",".claude/refs/karpathy-mnilax-best-solution.md (AB4.0, workspace-coupled baseline)"],"evidence":"2026-06-04-karpathy-mnilax-12-rule-universalization-research.md (8 papers, grep-verified)","generalization":"stack-agnostic + harness-agnostic","license_note":"Adapt freely. Tune the numbers (R6 budgets) to your model and cost structure.","type":"ruleset"},"headers":[],"relativePath":"research/reports/2026-06-04-12-rule-universal-ruleset.md","filePath":"research/reports/2026-06-04-12-rule-universal-ruleset.md","lastUpdated":1780842316000}'),a={name:"research/reports/2026-06-04-12-rule-universal-ruleset.md"};function s(i,t,d,l,c,u){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="the-12-rule-canon-for-ai-coding-agents-—-universal-edition" tabindex="-1">The 12-Rule Canon for AI Coding Agents — Universal Edition <a class="header-anchor" href="#the-12-rule-canon-for-ai-coding-agents-—-universal-edition" aria-label="Permalink to &quot;The 12-Rule Canon for AI Coding Agents — Universal Edition&quot;">​</a></h1><blockquote><p><strong>What this is.</strong> A portable discipline ruleset for <em>any</em> AI coding agent (Claude Code, Cursor, Copilot, Aider, Devin, a custom agent, or a human reviewing AI output) on <em>any</em> stack. Derived from Karpathy&#39;s R1–R4 + Mnilax&#39;s R5–R12, grounded in agent-failure research, stripped of any single tool&#39;s mechanisms.</p><p><strong>How to read each rule.</strong> Every rule is one triad: <strong>① Failure it prevents → ② Mechanism any team can adopt → ③ Mechanically-checkable verification.</strong> The third column is the point: a rule you cannot mechanically check is a vibe, not a rule.</p><p><strong>Why exactly 12.</strong> The original author observed compliance dropping from 76% to 52% past ~14 rules (self-reported). Keep your active ruleset ≤ 12. Adding a 13th means merging or cutting one.</p><p><strong>Evidence labels.</strong> Inline tags mean:</p><ul><li><strong>(Parallel: …)</strong> = an <em>analogous</em> failure mode observed in agent research. It does <strong>not</strong> prove the rule — it shows the same root-cause failure appearing in autonomous/multi-agent architectures. The rule prevents the assistant-discipline version of that failure.</li><li><strong>(Empirical: …)</strong> = a <em>directly measured</em> result from a cited paper (grep-verified against primary text).</li><li><strong>R1–R3 grounding is thinner than R4–R12</strong>: the papers study agent <em>architectures</em>, not single-assistant diff hygiene — so R2/R3 lean on analogy, R4–R12 on direct measurement.</li></ul></blockquote><hr><h2 id="r1-—-think-before-coding" tabindex="-1">R1 — Think Before Coding <a class="header-anchor" href="#r1-—-think-before-coding" aria-label="Permalink to &quot;R1 — Think Before Coding&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Acting on a silent assumption; hiding confusion instead of surfacing it. <em>(Parallel: MAST &quot;Fail to ask for clarification&quot; — acting on unclear/incomplete data → incorrect actions. arXiv:2503.13657)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>Before writing code, state in ≤2 sentences: your interpretation (not a restatement of the request) + key assumptions. If multiple interpretations exist, <strong>present them and let the human choose</strong> — don&#39;t pick silently. Calibrate ask-rate: trivial equivalent choices (naming, formatting, default values) → decide and note it in one line; <strong>scope changes or irreversible actions → always ask.</strong></td></tr><tr><td><strong>③ Verify</strong></td><td>Before the first edit, the transcript contains an explicit interpretation + assumptions line. For any destructive keyword (<code>DELETE</code> / <code>DROP</code> / <code>TRUNCATE</code> / prod deploy / key rotation / <code>rm -rf</code> / <code>--force</code> push / infra destroy), a confirmation summary was shown and acknowledged <strong>even if the human said &quot;just do it.&quot;</strong></td></tr></tbody></table><p><strong>Irreversible-action exception:</strong> the destructive keywords above always require a summary + wait, regardless of &quot;just do it.&quot; This is the one place &quot;Think Before&quot; is non-negotiable.</p><hr><h2 id="r2-—-simplicity-first" tabindex="-1">R2 — Simplicity First <a class="header-anchor" href="#r2-—-simplicity-first" aria-label="Permalink to &quot;R2 — Simplicity First&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Over-engineering: speculative features, single-use abstractions, error handling for impossible cases. <em>(Parallel: MAST — failures &quot;stem from system design issues, not just LLM limitations&quot;; adding complexity doesn&#39;t fix structural problems. arXiv:2503.13657)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>Write the minimum code that solves the stated problem. No feature beyond what was asked. <strong>Rule of 3:</strong> extract a helper only at the 3rd call site. Self-test: &quot;Would a senior engineer call this overcomplicated?&quot; If yes, rewrite smaller. If you wrote 200 lines and it could be 50, rewrite it.</td></tr><tr><td><strong>③ Verify</strong></td><td>Diff contains no abstraction with ❤️ call sites, no config/flag that wasn&#39;t requested, no error branch for an input that cannot occur. Line count is justifiable to a senior reviewer.</td></tr></tbody></table><p><strong>Security exception (always a shared function, exempt from Rule-of-3):</strong> crypto primitives, key operations, input validation, authentication. Never inline nonce/IV generation per-algorithm (→ IV-reuse vulnerability).</p><hr><h2 id="r3-—-surgical-changes" tabindex="-1">R3 — Surgical Changes <a class="header-anchor" href="#r3-—-surgical-changes" aria-label="Permalink to &quot;R3 — Surgical Changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Tangential refactoring, reformatting, renaming — noise that buries the real change. Wide-blast-radius edits also raise cascade risk. <em>(Parallel (thin — architecture-level, not diff-hygiene): SWE-agent &quot;Cascading Failed Edits&quot; = 23.4% of failures, the largest category; this grounds the cascade-risk half of R3 and overlaps R8. Scope-discipline itself is not directly measured in these papers. arXiv:2405.15793)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>Touch only what the task requires. Don&#39;t &quot;improve&quot; adjacent code/comments/formatting. Match existing style even if you&#39;d do it differently. Clean up only <strong>your own</strong> orphans (imports/vars your change made unused) — leave pre-existing dead code (mention it, don&#39;t delete).</td></tr><tr><td><strong>③ Verify</strong></td><td><strong>Every changed line traces directly to the request.</strong> Soft bounds: bug fix ≤ 50 lines, feature ≤ 300, single file ≤ 500. Unrelated bug found mid-task → logged &amp; reported, <strong>not</strong> auto-fixed (keeps commits atomic).</td></tr></tbody></table><p><strong>P0 security exception (fix on sight):</strong> hardcoded credentials, SQLi, path traversal, auth bypass. Isolate the fix on its own branch — don&#39;t bury a security patch inside a feature commit. Credential scans must exclude test/fixture/example/docs dirs to avoid drowning real leaks in fake data.</p><hr><h2 id="r4-—-goal-driven-execution" tabindex="-1">R4 — Goal-Driven Execution <a class="header-anchor" href="#r4-—-goal-driven-execution" aria-label="Permalink to &quot;R4 — Goal-Driven Execution&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Walking steps toward a weak goal (&quot;make it work&quot;) and stalling on the next step instead of converging on a verifiable outcome. <em>(Parallel: SWE-agent &quot;fast success, slow failure&quot; — resolved tasks median 12 steps/$1.21; unresolved 21 steps/$2.52, &quot;increasing budget unlikely to improve.&quot;)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>Transform the task into an observable success condition <strong>before</strong> starting, then loop to it: &quot;add validation&quot; → &quot;write tests for invalid inputs, then make them pass&quot;; &quot;fix the bug&quot; → &quot;write a test that reproduces it, then make it pass.&quot; For multi-step work, state a brief plan with a per-step check.</td></tr><tr><td><strong>③ Verify</strong></td><td>Success condition is <strong>mechanically checkable</strong> (a command exits 0 / a test passes / a specific output appears) — never &quot;looks correct.&quot; The verification command actually ran and its output is shown. <em>(Empirical payoff: Reflexion loop-until-<code>outcome.success</code> → 91% pass@1 vs one-shot GPT-4 80% on HumanEval. arXiv:2303.11366. Confucius makes verification a mandatory pipeline stage: &quot;if tests fail, the agent enters a debugging sub-loop.&quot; arXiv:2512.10398)</em></td></tr></tbody></table><hr><h2 id="r5-—-use-the-model-for-judgment-code-for-decisions" tabindex="-1">R5 — Use the Model for Judgment, Code for Decisions <a class="header-anchor" href="#r5-—-use-the-model-for-judgment-code-for-decisions" aria-label="Permalink to &quot;R5 — Use the Model for Judgment, Code for Decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Using the LLM where deterministic code belongs — routing, retries, status-code handling, math, transforms. Non-deterministic answers to deterministic questions.</td></tr><tr><td><strong>② Mechanism</strong></td><td><strong>LLM (latent/judgment):</strong> classification, drafting, summarization, extraction from unstructured text. <strong>Code (deterministic):</strong> routing, retries, HTTP status handling, arithmetic, format transforms. If a status code already answers the question, plain code answers the question.</td></tr><tr><td><strong>③ Verify</strong></td><td>No control-flow decision (route/retry/branch on a known signal) is delegated to a model call. <em>(Empirical: Dynamic Cheatsheet — once the model judged &quot;use a Python solver&quot; and let deterministic code compute, Game of 24 went 10%→99%; equation-balancing ~50%→98–100% while LLM-only &quot;baselines stagnated around 50%.&quot; arXiv:2504.07952)</em></td></tr></tbody></table><hr><h2 id="r6-—-token-budgets-are-not-advisory" tabindex="-1">R6 — Token Budgets Are Not Advisory <a class="header-anchor" href="#r6-—-token-budgets-are-not-advisory" aria-label="Permalink to &quot;R6 — Token Budgets Are Not Advisory&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Loops running until context is exhausted; quality degrading silently as context &quot;collapses.&quot; <em>(Parallel: ACE &quot;context collapse&quot; — &quot;iterative rewriting erodes details… sharp performance declines&quot;; DC &quot;context ballooning.&quot; arXiv:2510.04618 / 2504.07952)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>Set an explicit <strong>per-task</strong> and <strong>per-session</strong> token/cost budget for your model and price point. When approaching it, <strong>summarize and start fresh</strong> rather than pushing through. <strong>Surfacing the breach &gt; silently overrunning.</strong> When you do compact, use incremental/delta summaries that preserve goal + key results — don&#39;t full-rewrite (that <em>causes</em> collapse).</td></tr><tr><td><strong>③ Verify</strong></td><td>A budget number exists and is checked. On breach, the agent compacts or restarts and <strong>says so</strong> — it doesn&#39;t quietly continue. <em>(Empirical: Confucius — disabling semantic context management cost −6.6pp Resolve@1; persistent notes saved ~11k tokens &amp; 3 turns/task. arXiv:2512.10398)</em></td></tr></tbody></table><blockquote><p><strong>Universalization note:</strong> budget <em>numbers</em> are model- and cost-specific — set your own. The <em>principle</em> (explicit budgets + surface the breach) is universal. Don&#39;t ship someone else&#39;s specific token figures as if they were constants.</p></blockquote><hr><h2 id="r7-—-surface-conflicts-don-t-average-them" tabindex="-1">R7 — Surface Conflicts, Don&#39;t Average Them <a class="header-anchor" href="#r7-—-surface-conflicts-don-t-average-them" aria-label="Permalink to &quot;R7 — Surface Conflicts, Don&#39;t Average Them&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Blending two contradictory codebase patterns into &quot;average&quot; code that satisfies neither and is the worst of both. <em>(Parallel: MAST &quot;Inter-Agent Misalignment&quot; class — goal/instruction divergence resolved silently; coordinators need &quot;structured handoff + confirmation, not self-interpretation.&quot; arXiv:2503.13657)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>When two existing patterns contradict, <strong>pick one</strong> — by priority: ADR/CONTRIBUTING &gt; most recent commits &gt; test coverage. Explain why, and flag the other for cleanup. Never blend.</td></tr><tr><td><strong>③ Verify</strong></td><td>The chosen pattern is consistent (not a hybrid), and a <code>TODO(conflict): chose A over B; reason …; remove B before &lt;milestone&gt;</code> marker exists.</td></tr></tbody></table><hr><h2 id="r8-—-read-before-you-write" tabindex="-1">R8 — Read Before You Write <a class="header-anchor" href="#r8-—-read-before-you-write" aria-label="Permalink to &quot;R8 — Read Before You Write&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Adding code without understanding the interface contract or upstream impact. &quot;Looks orthogonal to me&quot; is the most dangerous phrase in any codebase.</td></tr><tr><td><strong>② Mechanism</strong></td><td>Before editing a file, read: its exports (interface contract) + the immediate caller (upstream impact) + obvious shared utilities (lateral deps). If you don&#39;t understand <em>why</em> existing code is structured a certain way, ask before adding to it.</td></tr><tr><td><strong>③ Verify</strong></td><td>The transcript shows the relevant exports/callers were read <strong>before</strong> the edit. <em>(Empirical: SWE-agent&#39;s successful trajectories open with find/read/reproduce (turns 1–4) then zoom-in dir→file→line; skipping it is costly — recovery rate collapses 90.5%→57.2% after the first failed edit. arXiv:2405.15793. Confucius enforces a Retrieval+Localization phase before Implementation. arXiv:2512.10398)</em></td></tr></tbody></table><hr><h2 id="r9-—-tests-verify-intent-not-just-behavior" tabindex="-1">R9 — Tests Verify Intent, Not Just Behavior <a class="header-anchor" href="#r9-—-tests-verify-intent-not-just-behavior" aria-label="Permalink to &quot;R9 — Tests Verify Intent, Not Just Behavior&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Tests that pass any implementation regardless of correctness. <code>expect(getUserName()).toBe(&#39;John&#39;)</code> is worthless if the function returns a hardcoded ID.</td></tr><tr><td><strong>② Mechanism</strong></td><td>Every test encodes <strong>why</strong> the behavior matters, not just <strong>what</strong> it does. Mock external boundaries, not the business core. The test: if you can&#39;t write a test that would <strong>fail when the business logic changes</strong>, the function is wrong.</td></tr><tr><td><strong>③ Verify</strong></td><td>Flip a line of business logic → at least one test fails. <em>(Empirical: Reflexion explicitly distinguishes &quot;explicit test cases&quot; from &quot;LLM self-evaluation&quot; as evaluators — the 91% result used the former. arXiv:2303.11366. SWE-bench-Pro required human-vetted test suites as ground truth — test <em>quality</em>, not presence, is what verifies intent. arXiv:2509.16941. SWE-agent&#39;s reproduction-first <code>(create, edit, python)</code> = write the failing case before the fix. arXiv:2405.15793)</em></td></tr></tbody></table><hr><h2 id="r10-—-checkpoint-after-every-significant-step" tabindex="-1">R10 — Checkpoint After Every Significant Step <a class="header-anchor" href="#r10-—-checkpoint-after-every-significant-step" aria-label="Permalink to &quot;R10 — Checkpoint After Every Significant Step&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Continuing from a state you can&#39;t describe; repeating already-done work. <em>(Parallel: MAST &quot;Loss of conversation history&quot; (context truncation → revert to stale state) + &quot;Step repetition.&quot; arXiv:2503.13657)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>After each step in a multi-step task, emit one line: <strong>what was done / what&#39;s verified / what&#39;s left.</strong> If you lose track, <strong>stop and restate</strong> — don&#39;t continue from an undescribable state.</td></tr><tr><td><strong>③ Verify</strong></td><td>A checkpoint line exists per major step and accurately reflects current state. <em>(Empirical: Confucius&#39;s &quot;Architect&quot; checkpoint preserves task spec + decisions + file paths + recent N messages; persistent notes save ~11k tokens, 3 turns/task and +1.4pp Resolve@1 by not re-discovering or repeating failed approaches. arXiv:2512.10398)</em></td></tr></tbody></table><hr><h2 id="r11-—-match-the-codebase-s-conventions-even-if-you-disagree" tabindex="-1">R11 — Match the Codebase&#39;s Conventions, Even If You Disagree <a class="header-anchor" href="#r11-—-match-the-codebase-s-conventions-even-if-you-disagree" aria-label="Permalink to &quot;R11 — Match the Codebase&#39;s Conventions, Even If You Disagree&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Silently forking convention (snake_case→camelCase, classes→hooks) on taste. Re-deriving what already exists. <em>(Parallel: DC — &quot;repeatedly re-discovering… the same solutions and mistakes&quot; is the cost of ignoring accumulated conventions; reusing the existing solution took Game of 24 10%→99%. arXiv:2504.07952)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>Inside the codebase, <strong>conformance &gt; taste.</strong> snake_case if it&#39;s snake_case; class-based if it&#39;s class-based. Disagreement is a separate conversation. Treat existing conventions as an <strong>evolving playbook</strong> — the authoritative starting point, not a blank slate. <em>(ACE &quot;evolving playbooks.&quot; arXiv:2510.04618)</em></td></tr><tr><td><strong>③ Verify</strong></td><td>New code matches surrounding style/naming/structure. If a convention is genuinely harmful (e.g., SQL string concatenation), it&#39;s surfaced as a flagged issue — <strong>not silently forked</strong>.</td></tr></tbody></table><hr><h2 id="r12-—-fail-loud" tabindex="-1">R12 — Fail Loud <a class="header-anchor" href="#r12-—-fail-loud" aria-label="Permalink to &quot;R12 — Fail Loud&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>① Prevents</strong></td><td>Silent failure masquerading as success. &quot;Migration completed&quot; when 30 records were skipped. &quot;Tests pass&quot; when some were skipped. &quot;Feature works&quot; when the asked-for edge case was never checked. <em>(Parallel: MAST&#39;s entire &quot;Task Verification&quot; class — the hardest to auto-fix — incl. &quot;Premature termination,&quot; &quot;No/incomplete verification&quot; (&quot;allowing errors to propagate undetected&quot;), plus &quot;Information withholding.&quot; arXiv:2503.13657)</em></td></tr><tr><td><strong>② Mechanism</strong></td><td>If you can&#39;t be sure something worked, <strong>say so explicitly.</strong> Default to surfacing uncertainty, not hiding it. Skipped steps and partial failures must be stated — tone can soften, <strong>information cannot be omitted.</strong> Report the count of what was skipped/failed, with a pointer to the log.</td></tr><tr><td><strong>③ Verify</strong></td><td>Before declaring done: the verification command ran and <strong>its output is shown</strong> (not a verbal &quot;tests pass&quot;). Any skip/partial-failure is named with a number. Truncated reads/searches are flagged, not silently assumed empty.</td></tr></tbody></table><hr><h2 id="appendix-a-—-compounding-engineering-the-meta-rule" tabindex="-1">Appendix A — Compounding Engineering (the meta-rule) <a class="header-anchor" href="#appendix-a-—-compounding-engineering-the-meta-rule" aria-label="Permalink to &quot;Appendix A — Compounding Engineering (the meta-rule)&quot;">​</a></h2><blockquote><p>Not one of the 12. A wrapper that keeps the 12 alive.</p></blockquote><p><strong>Every mistake is an opportunity to update the ruleset so it never recurs.</strong></p><ul><li><strong>Mechanism:</strong> after a mistake, ask &quot;will this recur?&quot; → if yes, add a guard (a hook/lint if mechanizable; otherwise a written rule). Record only <strong>verified</strong> constraints — never speculative &quot;expected behavior&quot; (that pollutes the ruleset).</li><li><strong>Verify:</strong> the same failure mode does not recur in the next session.</li><li><em>Empirical: ReasoningBank — agents that &quot;fail to learn from accumulated history… discard insights and repeat past errors&quot;; distilling lessons from successes AND failures is a &quot;new scaling dimension.&quot; arXiv:2509.25140. ACE&#39;s &quot;Reflector&quot; extracts &quot;what worked, what failed, and why.&quot; arXiv:2510.04618. A survey of 100+ papers calls memory &quot;indispensable for self-evolving capability.&quot; arXiv:2404.13501.</em></li><li><strong>Guard against the cliff:</strong> when active rules exceed ~14, compliance drops (self-reported 76%→52%). Merge or cut before adding.</li></ul><hr><h2 id="appendix-b-—-how-to-adopt-this-in-a-non-claude-harness" tabindex="-1">Appendix B — How to adopt this in a non-Claude harness <a class="header-anchor" href="#appendix-b-—-how-to-adopt-this-in-a-non-claude-harness" aria-label="Permalink to &quot;Appendix B — How to adopt this in a non-Claude harness&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept here</th><th>Cursor / Copilot / Aider / custom agent</th></tr></thead><tbody><tr><td>Surface interpretation before coding (R1)</td><td>Put R1 in your system prompt / <code>.cursorrules</code> / agent preamble</td></tr><tr><td>Independent reviewer pass (R4/R9/R12)</td><td>A second model (or human) reviews the full transcript before merge</td></tr><tr><td>Summarize &amp; restart on budget breach (R6)</td><td>Your harness&#39;s context-compaction or a fresh thread; set token caps in the runner</td></tr><tr><td>Verification command (R4/R12)</td><td>Wire your test/lint/build command as a required gate (CI or pre-commit)</td></tr><tr><td>Checkpoint line (R10)</td><td>Have the agent write a running notes file; reload it next session</td></tr><tr><td>Update-on-mistake (Appendix A)</td><td>A <code>LESSONS.md</code> / <code>GOTCHAS.md</code> the agent reads at session start</td></tr></tbody></table><p><strong>The rules are the contract; the mechanisms are interchangeable.</strong> Any harness that lets you (1) inject a system prompt, (2) run a verification command, and (3) persist notes across sessions can implement all 12.</p><hr><h2 id="appendix-c-—-one-line-cheat-sheet" tabindex="-1">Appendix C — One-line cheat sheet <a class="header-anchor" href="#appendix-c-—-one-line-cheat-sheet" aria-label="Permalink to &quot;Appendix C — One-line cheat sheet&quot;">​</a></h2><ol><li><strong>Think</strong> before coding — surface assumptions, ask on ambiguity.</li><li><strong>Simplest</strong> code that works — no speculation.</li><li><strong>Surgical</strong> edits — every line traces to the request.</li><li><strong>Goal-driven</strong> — define a checkable success condition, loop to it.</li><li><strong>Judgment</strong> to the model, <strong>decisions</strong> to code.</li><li><strong>Budgets</strong> are hard — surface the breach, don&#39;t overrun.</li><li><strong>Surface</strong> conflicts — pick one, never average.</li><li><strong>Read</strong> before you write.</li><li><strong>Tests</strong> verify intent — must fail when logic changes.</li><li><strong>Checkpoint</strong> — describe state every step.</li><li><strong>Conform</strong> to conventions — disagree elsewhere.</li><li><strong>Fail loud</strong> — uncertainty surfaced, not hidden.</li></ol>',54)])])}const m=e(a,[["render",s]]);export{g as __pageData,m as default};
